import heapq

def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits: raise KeyError(src)
    if dst not in limits: raise KeyError(dst)
    if src == dst: raise ValueError("src and dst cannot be the same")
    best: Dict[str, Tuple[int, List[str]]] = {}
    INF = 10**18
    best[src] = (INF, [src])
    pq = [(-INF, (src,), src, [src])]
    while pq:
        neg_bn, path_tuple, node, path = heapq.heappop(pq)
        bn = -neg_bn
        if node in best:
            ex_bn, ex_path = best[node]
            if bn < ex_bn or (bn == ex_bn and list(path_tuple) > ex_path): continue
        best[node] = (bn, list(path_tuple))
        if node == dst: return (bn, list(path_tuple))
        neighbors = limits.get(node, {})
        for nxt in sorted(neighbors.keys()):
            w = neighbors[nxt]
            new_bn = min(bn, w)
            new_path = list(path_tuple) + [nxt]
            new_tuple = tuple(new_path)
            if nxt in best:
                ex_bn, ex_path = best[nxt]
                if new_bn < ex_bn or (new_bn == ex_bn and new_path > ex_path): continue
            heapq.heappush(pq, (-new_bn, new_tuple, nxt, new_path))
    return None"}}

